async function main() {
  const course = await p.course.findUnique({
    where: { code: 'SCRATCH-KIDS' },
    include: { subjects: { orderBy: { order: 'asc' } } },
  })
  if (!course) { console.error('❌ Course SCRATCH-KIDS not found!'); process.exit(1) }
  console.log(`🐱 Found course: ${course.name} (${course.subjects.length} subjects)\n`)

  let totalCreated = 0
  for (const topicData of TOPICS) {
    const subject = course.subjects.find(s => s.order === topicData.order)
    if (!subject) { console.log(`⚠️  Skip order ${topicData.order} — subject not found`); continue }

    const existing = await p.question.count({ where: { subjectId: subject.id } })
    if (existing > 0) {
      console.log(`⏩ Skip: [${topicData.order}] ${topicData.topicName} — ${existing} câu đã có`)
      continue
    }

    await p.question.createMany({
      data: topicData.questions.map((q, i) => ({
        subjectId: subject.id,
        order: i + 1,
        questionType: q.type,
        content: q.content,
        options: q.options,
        correctAnswer: q.answer,
        explanation: q.explanation,
        points: 1,
      })),
    })
    console.log(`✅ [${topicData.order}] ${topicData.topicName} — ${topicData.questions.length} câu`)
    totalCreated += topicData.questions.length
  }

  console.log(`\n🎉 Done! Tổng cộng ${totalCreated} câu hỏi mới được tạo.`)
  await p.$disconnect()
}

main().catch(e => { console.error('❌', e.message); p.$disconnect(); process.exit(1) })
